void Solver::bump_var(int var, double coeff) {
    const double THRESH = 1e100;
    const double SCALE  = 1e-100;

    // increase activity of the variable
    double inc = var_inc * coeff;
    activity[var] += inc;

    // if any activity exceeds the threshold, uniformly down‑scale all activities
    if (activity[var] > THRESH) {
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= SCALE;
        }
        var_inc *= SCALE;
    }

    // keep the VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
